# owner: platform
import unittest

from hourglass.errors import ProjectError
from hourglass.models import Shift
from hourglass.parsing import parse_span
from hourglass.timesheet import timesheet_lines


def _shift(worker, span):
    return Shift(worker, "mon", parse_span(span))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        lines = timesheet_lines(
            [
                _shift("Ana", "09:00-10:30"),
                _shift("Ben", "09:00-13:00"),
                _shift("Ana", "11:00-12:00")
            ]
        )
        self.assertEqual(
            lines,
            [
                "Ben: 1 shifts, 4.0 hours",
                "Ana: 2 shifts, 2.5 hours"
            ]
        )

    def test_empty(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([_shift("  ", "09:00-10:00")])
